16: std::print(stderr, "Ожидался разделитель \"--\" на 5-й позиции, получено: {}\n", argv[5]);
17: return 1;
18: }
19: 
20: int expected_code = 0;
21: 
22: try{
23: expected_code = std::stoi(argv[1]);
24: } catch (const std::invalid_argument&) {
25: std::print(stderr, "Ожидаемый exit-code - целое число. Получено: {}\n", argv[1]);
26: return 1;
27: } catch (const std::out_of_range&) {
28: std::print(stderr, "Ожидается exit-code типа int, а полученное число({}) - за пределами int.\n", argv[1]);
29: return 1;
30: }
31: 
32: #ifdef _WIN32
33: // нет копирования и наследования типа fork(), поэтому детальная информация для каждого нового процесса
34: 
35: // дескриптор безопасности для объектов, которые созданы/открыты внутри программы (для файлов in/out/err)
36: SECURITY_ATTRIBUTES sa{};
37: sa.nLength = sizeof(sa); // размер структ. в байтах; будет размер самого SECURITY_ATTRIBUTES
38: sa.bInheritHandle = true; // хэндл с этим sa может наследоваться дочерним процессом
